\documentclass{beamer}
\usetheme{Madrid}
\title{Backyard Beekeeping: Spring Management}
\author{Community Workshop Series}
\date{April 2026}
\begin{document}

\begin{frame}
\titlepage
\end{frame}

\begin{frame}{Checking the Colony}
After winter, the first inspection sets up the whole season.
\begin{itemize}
\item Confirm the queen is present and laying.
\item Estimate food stores; feed syrup if below two frames of honey.
\item Scrape out old, dark comb and replace it with fresh foundation.
\end{itemize}
\end{frame}

\begin{frame}{Swarm Prevention}
Strong colonies will try to swarm in late spring.
\begin{itemize}
\item Add a super before the brood box is full.
\item Split booming colonies in late April.
\item Mark the queen during the first inspection so she is easy to find.
\end{itemize}
\end{frame}

\begin{frame}{Forage Planning}
Colonies need continuous forage from April onward.
\begin{itemize}
\item Plant early bloomers near the apiary.
\item Keep a water source within fifty metres of the hives.
\end{itemize}
\end{frame}

\begin{frame}{Wrap-Up}
Inspect weekly, keep notes, and enjoy the season.
\end{frame}

\end{document}

